import numpy as np

from dg5f_grasp_control.hand_model import FINGER_JOINT_INDEX


def tesollo_forward_kinematics(q):
    s = np.sin(q)
    c = np.cos(q)
    x = np.zeros(15, dtype=np.float64)

    x[0] = 0.0318*s[1]*s[2]*s[3] - 0.0318*s[1]*c[2]*c[3] - 0.0334*s[1]*c[2] - 0.0381*s[1] + 0.0279
    x[1] = 0.0318*(-s[0]*s[2] + c[0]*c[1]*c[2])*c[3] + 0.0318*(-s[0]*c[2] - s[2]*c[0]*c[1])*s[3] - 0.0334*s[0]*s[2] + 0.0334*c[0]*c[1]*c[2] + 0.0381*c[0]*c[1] + 0.018
    x[2] = 0.0318*(-s[0]*s[2]*c[1] + c[0]*c[2])*s[3] + 0.0318*(s[0]*c[1]*c[2] + s[2]*c[0])*c[3] + 0.0334*s[0]*c[1]*c[2] + 0.0381*s[0]*c[1] + 0.0334*s[2]*c[0] + 0.0298

    x[3] = 0.01978*(-s[5]*s[6] + c[5]*c[6])*s[7] + 0.01978*(s[5]*c[6] + s[6]*c[5])*c[7] + 0.0334*s[5]*c[6] + 0.0334*s[5] + 0.0334*s[6]*c[5] + 0.0143
    x[4] = 0.01978*(s[4]*s[5]*s[6] - s[4]*c[5]*c[6])*c[7] + 0.01978*(s[4]*s[5]*c[6] + s[4]*s[6]*c[5])*s[7] + 0.0334*s[4]*s[5]*s[6] - 0.0334*s[4]*c[5]*c[6] - 0.0334*s[4]*c[5] - 0.02415*s[4] + 0.028
    x[5] = 0.01978*(-s[5]*s[6]*c[4] + c[4]*c[5]*c[6])*c[7] + 0.01978*(-s[5]*c[4]*c[6] - s[6]*c[4]*c[5])*s[7] - 0.0334*s[5]*s[6]*c[4] + 0.0334*c[4]*c[5]*c[6] + 0.0334*c[4]*c[5] + 0.02415*c[4] + 0.08365

    x[6] = 0.0209*(-s[10]*s[9] + c[10]*c[9])*s[11] + 0.0209*(s[10]*c[9] + s[9]*c[10])*c[11] + 0.0334*s[10]*c[9] + 0.0334*s[9]*c[10] + 0.0334*s[9] + 0.0143
    x[7] = 0.0209*(s[10]*s[8]*s[9] - s[8]*c[10]*c[9])*c[11] + 0.0209*(s[10]*s[8]*c[9] + s[8]*s[9]*c[10])*s[11] + 0.0334*s[10]*s[8]*s[9] - 0.0334*s[8]*c[10]*c[9] - 0.0334*s[8]*c[9] - 0.02415*s[8] + 0.005
    x[8] = 0.0209*(-s[10]*s[9]*c[8] + c[10]*c[8]*c[9])*c[11] + 0.0209*(-s[10]*c[8]*c[9] - s[9]*c[10]*c[8])*s[11] - 0.0334*s[10]*s[9]*c[8] + 0.0334*c[10]*c[8]*c[9] + 0.0334*c[8]*c[9] + 0.02415*c[8] + 0.08865

    x[9] = 0.0209*(-s[13]*s[14] + c[13]*c[14])*s[15] + 0.0209*(s[13]*c[14] + s[14]*c[13])*c[15] + 0.0334*s[13]*c[14] + 0.0334*s[13] + 0.0334*s[14]*c[13] + 0.0143
    x[10] = 0.0209*(s[12]*s[13]*s[14] - s[12]*c[13]*c[14])*c[15] + 0.0209*(s[12]*s[13]*c[14] + s[12]*s[14]*c[13])*s[15] + 0.0334*s[12]*s[13]*s[14] - 0.0334*s[12]*c[13]*c[14] - 0.0334*s[12]*c[13] - 0.02415*s[12] - 0.018
    x[11] = 0.0209*(-s[13]*s[14]*c[12] + c[12]*c[13]*c[14])*c[15] + 0.0209*(-s[13]*c[12]*c[14] - s[14]*c[12]*c[13])*s[15] - 0.0334*s[13]*s[14]*c[12] + 0.0334*c[12]*c[13]*c[14] + 0.0334*c[12]*c[13] + 0.02415*c[12] + 0.08065

    x[12] = 0.0318*(-s[16]*s[17]*s[18] + c[16]*c[18])*s[19] + 0.0318*(s[16]*s[17]*c[18] + s[18]*c[16])*c[19] + 0.0334*s[16]*s[17]*c[18] + 0.0272*s[16]*s[17] + 0.02445*s[16] + 0.0334*s[18]*c[16] + 0.013
    x[13] = 0.0318*(s[16]*s[18] - s[17]*c[16]*c[18])*c[19] + 0.0318*(s[16]*c[18] + s[17]*s[18]*c[16])*s[19] + 0.0334*s[16]*s[18] - 0.0334*s[17]*c[16]*c[18] - 0.0272*s[17]*c[16] - 0.02445*c[16] - 0.01805
    x[14] = -0.0318*s[18]*s[19]*c[17] + 0.0318*c[17]*c[18]*c[19] + 0.0334*c[17]*c[18] + 0.0272*c[17] + 0.0671

    return x.reshape(5, 3)


def tesollo_jacobian(q):
    s = np.sin(q)
    c = np.cos(q)
    ja = np.zeros((15, 20), dtype=np.float64)

    ja[0, 1] = 0.0318*s[2]*s[3]*c[1] - 0.0318*c[1]*c[2]*c[3] - 0.0334*c[1]*c[2] - 0.0381*c[1]
    ja[0, 2] = 0.0318*s[1]*s[2]*c[3] + 0.0334*s[1]*s[2] + 0.0318*s[1]*s[3]*c[2]
    ja[0, 3] = 0.0318*s[1]*s[2]*c[3] + 0.0318*s[1]*s[3]*c[2]
    ja[1, 0] = 0.0318*(s[0]*s[2]*c[1] - c[0]*c[2])*s[3] + 0.0318*(-s[0]*c[1]*c[2] - s[2]*c[0])*c[3] - 0.0334*s[0]*c[1]*c[2] - 0.0381*s[0]*c[1] - 0.0334*s[2]*c[0]
    ja[1, 1] = 0.0318*s[1]*s[2]*s[3]*c[0] - 0.0318*s[1]*c[0]*c[2]*c[3] - 0.0334*s[1]*c[0]*c[2] - 0.0381*s[1]*c[0]
    ja[1, 2] = 0.0318*(s[0]*s[2] - c[0]*c[1]*c[2])*s[3] + 0.0318*(-s[0]*c[2] - s[2]*c[0]*c[1])*c[3] - 0.0334*s[0]*c[2] - 0.0334*s[2]*c[0]*c[1]
    ja[1, 3] = -0.0318*(-s[0]*s[2] + c[0]*c[1]*c[2])*s[3] + 0.0318*(-s[0]*c[2] - s[2]*c[0]*c[1])*c[3]
    ja[2, 0] = 0.0318*(-s[0]*s[2] + c[0]*c[1]*c[2])*c[3] + 0.0318*(-s[0]*c[2] - s[2]*c[0]*c[1])*s[3] - 0.0334*s[0]*s[2] + 0.0334*c[0]*c[1]*c[2] + 0.0381*c[0]*c[1]
    ja[2, 1] = 0.0318*s[0]*s[1]*s[2]*s[3] - 0.0318*s[0]*s[1]*c[2]*c[3] - 0.0334*s[0]*s[1]*c[2] - 0.0381*s[0]*s[1]
    ja[2, 2] = 0.0318*(-s[0]*s[2]*c[1] + c[0]*c[2])*c[3] + 0.0318*(-s[0]*c[1]*c[2] - s[2]*c[0])*s[3] - 0.0334*s[0]*s[2]*c[1] + 0.0334*c[0]*c[2]
    ja[2, 3] = 0.0318*(-s[0]*s[2]*c[1] + c[0]*c[2])*c[3] - 0.0318*(s[0]*c[1]*c[2] + s[2]*c[0])*s[3]

    ja[3, 5] = 0.01978*(-s[5]*s[6] + c[5]*c[6])*c[7] + 0.01978*(-s[5]*c[6] - s[6]*c[5])*s[7] - 0.0334*s[5]*s[6] + 0.0334*c[5]*c[6] + 0.0334*c[5]
    ja[3, 6] = 0.01978*(-s[5]*s[6] + c[5]*c[6])*c[7] + 0.01978*(-s[5]*c[6] - s[6]*c[5])*s[7] - 0.0334*s[5]*s[6] + 0.0334*c[5]*c[6]
    ja[3, 7] = 0.01978*(-s[5]*s[6] + c[5]*c[6])*c[7] - 0.01978*(s[5]*c[6] + s[6]*c[5])*s[7]
    ja[4, 4] = 0.01978*(s[5]*s[6]*c[4] - c[4]*c[5]*c[6])*c[7] + 0.01978*(s[5]*c[4]*c[6] + s[6]*c[4]*c[5])*s[7] + 0.0334*s[5]*s[6]*c[4] - 0.0334*c[4]*c[5]*c[6] - 0.0334*c[4]*c[5] - 0.02415*c[4]
    ja[4, 5] = 0.01978*(-s[4]*s[5]*s[6] + s[4]*c[5]*c[6])*s[7] + 0.01978*(s[4]*s[5]*c[6] + s[4]*s[6]*c[5])*c[7] + 0.0334*s[4]*s[5]*c[6] + 0.0334*s[4]*s[5] + 0.0334*s[4]*s[6]*c[5]
    ja[4, 6] = 0.01978*(-s[4]*s[5]*s[6] + s[4]*c[5]*c[6])*s[7] + 0.01978*(s[4]*s[5]*c[6] + s[4]*s[6]*c[5])*c[7] + 0.0334*s[4]*s[5]*c[6] + 0.0334*s[4]*s[6]*c[5]
    ja[4, 7] = -0.01978*(s[4]*s[5]*s[6] - s[4]*c[5]*c[6])*s[7] + 0.01978*(s[4]*s[5]*c[6] + s[4]*s[6]*c[5])*c[7]
    ja[5, 4] = 0.01978*(s[4]*s[5]*s[6] - s[4]*c[5]*c[6])*c[7] + 0.01978*(s[4]*s[5]*c[6] + s[4]*s[6]*c[5])*s[7] + 0.0334*s[4]*s[5]*s[6] - 0.0334*s[4]*c[5]*c[6] - 0.0334*s[4]*c[5] - 0.02415*s[4]
    ja[5, 5] = 0.01978*(s[5]*s[6]*c[4] - c[4]*c[5]*c[6])*s[7] + 0.01978*(-s[5]*c[4]*c[6] - s[6]*c[4]*c[5])*c[7] - 0.0334*s[5]*c[4]*c[6] - 0.0334*s[5]*c[4] - 0.0334*s[6]*c[4]*c[5]
    ja[5, 6] = 0.01978*(s[5]*s[6]*c[4] - c[4]*c[5]*c[6])*s[7] + 0.01978*(-s[5]*c[4]*c[6] - s[6]*c[4]*c[5])*c[7] - 0.0334*s[5]*c[4]*c[6] - 0.0334*s[6]*c[4]*c[5]
    ja[5, 7] = -0.01978*(-s[5]*s[6]*c[4] + c[4]*c[5]*c[6])*s[7] + 0.01978*(-s[5]*c[4]*c[6] - s[6]*c[4]*c[5])*c[7]

    ja[6, 9] = 0.0209*(-s[10]*s[9] + c[10]*c[9])*c[11] + 0.0209*(-s[10]*c[9] - s[9]*c[10])*s[11] - 0.0334*s[10]*s[9] + 0.0334*c[10]*c[9] + 0.0334*c[9]
    ja[6, 10] = 0.0209*(-s[10]*s[9] + c[10]*c[9])*c[11] + 0.0209*(-s[10]*c[9] - s[9]*c[10])*s[11] - 0.0334*s[10]*s[9] + 0.0334*c[10]*c[9]
    ja[6, 11] = 0.0209*(-s[10]*s[9] + c[10]*c[9])*c[11] - 0.0209*(s[10]*c[9] + s[9]*c[10])*s[11]
    ja[7, 8] = 0.0209*(s[10]*s[9]*c[8] - c[10]*c[8]*c[9])*c[11] + 0.0209*(s[10]*c[8]*c[9] + s[9]*c[10]*c[8])*s[11] + 0.0334*s[10]*s[9]*c[8] - 0.0334*c[10]*c[8]*c[9] - 0.0334*c[8]*c[9] - 0.02415*c[8]
    ja[7, 9] = 0.0209*(-s[10]*s[8]*s[9] + s[8]*c[10]*c[9])*s[11] + 0.0209*(s[10]*s[8]*c[9] + s[8]*s[9]*c[10])*c[11] + 0.0334*s[10]*s[8]*c[9] + 0.0334*s[8]*s[9]*c[10] + 0.0334*s[8]*s[9]
    ja[7, 10] = 0.0209*(-s[10]*s[8]*s[9] + s[8]*c[10]*c[9])*s[11] + 0.0209*(s[10]*s[8]*c[9] + s[8]*s[9]*c[10])*c[11] + 0.0334*s[10]*s[8]*c[9] + 0.0334*s[8]*s[9]*c[10]
    ja[7, 11] = -0.0209*(s[10]*s[8]*s[9] - s[8]*c[10]*c[9])*s[11] + 0.0209*(s[10]*s[8]*c[9] + s[8]*s[9]*c[10])*c[11]
    ja[8, 8] = 0.0209*(s[10]*s[8]*s[9] - s[8]*c[10]*c[9])*c[11] + 0.0209*(s[10]*s[8]*c[9] + s[8]*s[9]*c[10])*s[11] + 0.0334*s[10]*s[8]*s[9] - 0.0334*s[8]*c[10]*c[9] - 0.0334*s[8]*c[9] - 0.02415*s[8]
    ja[8, 9] = 0.0209*(s[10]*s[9]*c[8] - c[10]*c[8]*c[9])*s[11] + 0.0209*(-s[10]*c[8]*c[9] - s[9]*c[10]*c[8])*c[11] - 0.0334*s[10]*c[8]*c[9] - 0.0334*s[9]*c[10]*c[8] - 0.0334*s[9]*c[8]
    ja[8, 10] = 0.0209*(s[10]*s[9]*c[8] - c[10]*c[8]*c[9])*s[11] + 0.0209*(-s[10]*c[8]*c[9] - s[9]*c[10]*c[8])*c[11] - 0.0334*s[10]*c[8]*c[9] - 0.0334*s[9]*c[10]*c[8]
    ja[8, 11] = -0.0209*(-s[10]*s[9]*c[8] + c[10]*c[8]*c[9])*s[11] + 0.0209*(-s[10]*c[8]*c[9] - s[9]*c[10]*c[8])*c[11]

    ja[9, 13] = 0.0209*(-s[13]*s[14] + c[13]*c[14])*c[15] + 0.0209*(-s[13]*c[14] - s[14]*c[13])*s[15] - 0.0334*s[13]*s[14] + 0.0334*c[13]*c[14] + 0.0334*c[13]
    ja[9, 14] = 0.0209*(-s[13]*s[14] + c[13]*c[14])*c[15] + 0.0209*(-s[13]*c[14] - s[14]*c[13])*s[15] - 0.0334*s[13]*s[14] + 0.0334*c[13]*c[14]
    ja[9, 15] = 0.0209*(-s[13]*s[14] + c[13]*c[14])*c[15] - 0.0209*(s[13]*c[14] + s[14]*c[13])*s[15]
    ja[10, 12] = 0.0209*(s[13]*s[14]*c[12] - c[12]*c[13]*c[14])*c[15] + 0.0209*(s[13]*c[12]*c[14] + s[14]*c[12]*c[13])*s[15] + 0.0334*s[13]*s[14]*c[12] - 0.0334*c[12]*c[13]*c[14] - 0.0334*c[12]*c[13] - 0.02415*c[12]
    ja[10, 13] = 0.0209*(-s[12]*s[13]*s[14] + s[12]*c[13]*c[14])*s[15] + 0.0209*(s[12]*s[13]*c[14] + s[12]*s[14]*c[13])*c[15] + 0.0334*s[12]*s[13]*c[14] + 0.0334*s[12]*s[13] + 0.0334*s[12]*s[14]*c[13]
    ja[10, 14] = 0.0209*(-s[12]*s[13]*s[14] + s[12]*c[13]*c[14])*s[15] + 0.0209*(s[12]*s[13]*c[14] + s[12]*s[14]*c[13])*c[15] + 0.0334*s[12]*s[13]*c[14] + 0.0334*s[12]*s[14]*c[13]
    ja[10, 15] = -0.0209*(s[12]*s[13]*s[14] - s[12]*c[13]*c[14])*s[15] + 0.0209*(s[12]*s[13]*c[14] + s[12]*s[14]*c[13])*c[15]
    ja[11, 12] = 0.0209*(s[12]*s[13]*s[14] - s[12]*c[13]*c[14])*c[15] + 0.0209*(s[12]*s[13]*c[14] + s[12]*s[14]*c[13])*s[15] + 0.0334*s[12]*s[13]*s[14] - 0.0334*s[12]*c[13]*c[14] - 0.0334*s[12]*c[13] - 0.02415*s[12]
    ja[11, 13] = 0.0209*(s[13]*s[14]*c[12] - c[12]*c[13]*c[14])*s[15] + 0.0209*(-s[13]*c[12]*c[14] - s[14]*c[12]*c[13])*c[15] - 0.0334*s[13]*c[12]*c[14] - 0.0334*s[13]*c[12] - 0.0334*s[14]*c[12]*c[13]
    ja[11, 14] = 0.0209*(s[13]*s[14]*c[12] - c[12]*c[13]*c[14])*s[15] + 0.0209*(-s[13]*c[12]*c[14] - s[14]*c[12]*c[13])*c[15] - 0.0334*s[13]*c[12]*c[14] - 0.0334*s[14]*c[12]*c[13]
    ja[11, 15] = -0.0209*(-s[13]*s[14]*c[12] + c[12]*c[13]*c[14])*s[15] + 0.0209*(-s[13]*c[12]*c[14] - s[14]*c[12]*c[13])*c[15]

    ja[12, 16] = 0.0318*(-s[16]*s[18] + s[17]*c[16]*c[18])*c[19] + 0.0318*(-s[16]*c[18] - s[17]*s[18]*c[16])*s[19] - 0.0334*s[16]*s[18] + 0.0334*s[17]*c[16]*c[18] + 0.0272*s[17]*c[16] + 0.02445*c[16]
    ja[12, 17] = -0.0318*s[16]*s[18]*s[19]*c[17] + 0.0318*s[16]*c[17]*c[18]*c[19] + 0.0334*s[16]*c[17]*c[18] + 0.0272*s[16]*c[17]
    ja[12, 18] = 0.0318*(-s[16]*s[17]*s[18] + c[16]*c[18])*c[19] + 0.0318*(-s[16]*s[17]*c[18] - s[18]*c[16])*s[19] - 0.0334*s[16]*s[17]*s[18] + 0.0334*c[16]*c[18]
    ja[12, 19] = 0.0318*(-s[16]*s[17]*s[18] + c[16]*c[18])*c[19] - 0.0318*(s[16]*s[17]*c[18] + s[18]*c[16])*s[19]
    ja[13, 16] = 0.0318*(-s[16]*s[17]*s[18] + c[16]*c[18])*s[19] + 0.0318*(s[16]*s[17]*c[18] + s[18]*c[16])*c[19] + 0.0334*s[16]*s[17]*c[18] + 0.0272*s[16]*s[17] + 0.02445*s[16] + 0.0334*s[18]*c[16]
    ja[13, 17] = 0.0318*s[18]*s[19]*c[16]*c[17] - 0.0318*c[16]*c[17]*c[18]*c[19] - 0.0334*c[16]*c[17]*c[18] - 0.0272*c[16]*c[17]
    ja[13, 18] = 0.0318*(-s[16]*s[18] + s[17]*c[16]*c[18])*s[19] + 0.0318*(s[16]*c[18] + s[17]*s[18]*c[16])*c[19] + 0.0334*s[16]*c[18] + 0.0334*s[17]*s[18]*c[16]
    ja[13, 19] = -0.0318*(s[16]*s[18] - s[17]*c[16]*c[18])*s[19] + 0.0318*(s[16]*c[18] + s[17]*s[18]*c[16])*c[19]
    ja[14, 17] = 0.0318*s[17]*s[18]*s[19] - 0.0318*s[17]*c[18]*c[19] - 0.0334*s[17]*c[18] - 0.0272*s[17]
    ja[14, 18] = -0.0318*s[18]*c[17]*c[19] - 0.0334*s[18]*c[17] - 0.0318*s[19]*c[17]*c[18]
    ja[14, 19] = -0.0318*s[18]*c[17]*c[19] - 0.0318*s[19]*c[17]*c[18]

    return ja


def tip_position(q, finger):
    return tesollo_forward_kinematics(q)[finger - 1].copy()


def tip_jacobian(q, finger, eps=1e-6):
    del eps
    idxs = FINGER_JOINT_INDEX[finger]
    rows = slice(3 * (finger - 1), 3 * finger)
    return tesollo_jacobian(q)[rows, idxs].copy()
